INSERT INTO `ai_chat_message` VALUES (1, 1, 'user', '您好', NULL, '2026-05-03 00:29:06');
INSERT INTO `ai_chat_message` VALUES (2, 1, 'assistant', '您好！我是招生平台的AI助手，很高兴为您服务。请问有什么可以帮助您的？您可以咨询院校专业信息、查看报名状态、查询录取结果或浏览最新资讯公告。', '[{\"type\":\"university\",\"id\":\"2049941395174621185\",\"title\":\"222\"},{\"type\":\"university\",\"id\":\"1685514620438\",\"title\":\"22225\"},{\"type\":\"university\",\"id\":\"21\",\"title\":\"学校名称1\"},{\"type\":\"university\",\"id\":\"22\",\"title\":\"学校名称2\"},{\"type\":\"university\",\"id\":\"23\",\"title\":\"学校名称3\"},{\"type\":\"major\",\"id\":\"41\",\"title\":\"专业名称1\"},{\"type\":\"major\",\"id\":\"42\",\"title\":\"专业名称2\"},{\"type\":\"major\",\"id\":\"43\",\"title\":\"专业名称3\"},{\"type\":\"major\",\"id\":\"44\",\"title\":\"专业名称4\"},{\"type\":\"major\",\"id\":\"45\",\"title\":\"专业名称5\"},{\"type\":\"news\",\"id\":\"118\",\"title\":\"坚持才会成功\"},{\"type\":\"news\",\"id\":\"117\",\"title\":\"Leave未必是一种痛苦\"},{\"type\":\"news\",\"id\":\"116\",\"title\":\"离开是一种痛苦，是一种勇气，但同样也是一个考验，是一个新的开端\"},{\"type\":\"news\",\"id\":\"115\",\"title\":\"你要去相信，没有到不了的明天\"},{\"type\":\"news\",\"id\":\"114\",\"title\":\"挫折是另一个生命的开端\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"关于我们\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"系统简介\"}]', '2026-05-03 00:29:10');
INSERT INTO `ai_chat_message` VALUES (3, 1, 'user', '现在有那些学校？', NULL, '2026-05-03 00:29:27');
INSERT INTO `ai_chat_message` VALUES (4, 1, 'assistant', '根据数据库中的公开信息，当前有以下学校可供参考：\n\n1. **222** -类型：222 -层次：22 -电话：22 -简介：2222. **22225** -类型：5555 -层次：555 -电话：555 -简介：555555555555555555553. **学校名称1** -类型：公办 -层次：985 -电话：联系方式1 -简介：学校简介14. **学校名称2** -类型：公办 -层次：985 -电话：联系方式2 -简介：学校简介25. **学校名称3** -类型：公办 -层次：985 -电话：联系方式3 -简介：学校简介3以上是全部公开院校数据，如需了解具体专业或招生详情，请进一步询问。', '[{\"type\":\"university\",\"id\":\"2049941395174621185\",\"title\":\"222\"},{\"type\":\"university\",\"id\":\"1685514620438\",\"title\":\"22225\"},{\"type\":\"university\",\"id\":\"21\",\"title\":\"学校名称1\"},{\"type\":\"university\",\"id\":\"22\",\"title\":\"学校名称2\"},{\"type\":\"university\",\"id\":\"23\",\"title\":\"学校名称3\"},{\"type\":\"major\",\"id\":\"41\",\"title\":\"专业名称1\"},{\"type\":\"major\",\"id\":\"42\",\"title\":\"专业名称2\"},{\"type\":\"major\",\"id\":\"43\",\"title\":\"专业名称3\"},{\"type\":\"major\",\"id\":\"44\",\"title\":\"专业名称4\"},{\"type\":\"major\",\"id\":\"45\",\"title\":\"专业名称5\"},{\"type\":\"news\",\"id\":\"118\",\"title\":\"坚持才会成功\"},{\"type\":\"news\",\"id\":\"117\",\"title\":\"Leave未必是一种痛苦\"},{\"type\":\"news\",\"id\":\"116\",\"title\":\"离开是一种痛苦，是一种勇气，但同样也是一个考验，是一个新的开端\"},{\"type\":\"news\",\"id\":\"115\",\"title\":\"你要去相信，没有到不了的明天\"},{\"type\":\"news\",\"id\":\"114\",\"title\":\"挫折是另一个生命的开端\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"关于我们\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"系统简介\"}]', '2026-05-03 00:29:33');
INSERT INTO `ai_chat_message` VALUES (5, 1, 'user', '你是谁？', NULL, '2026-05-03 00:36:48');
INSERT INTO `ai_chat_message` VALUES (6, 1, 'assistant', '我是你所在的大学招生平台的AI助手。我可以根据数据库中的信息，帮助你查询公开的院校、专业、资讯，以及你个人的报名、收藏、成绩和录取等信息。请告诉我你有什么需要帮助的？', '[{\"type\":\"university\",\"id\":\"2049941395174621185\",\"title\":\"222\"},{\"type\":\"university\",\"id\":\"1685514620438\",\"title\":\"22225\"},{\"type\":\"university\",\"id\":\"21\",\"title\":\"学校名称1\"},{\"type\":\"university\",\"id\":\"22\",\"title\":\"学校名称2\"},{\"type\":\"university\",\"id\":\"23\",\"title\":\"学校名称3\"},{\"type\":\"major\",\"id\":\"41\",\"title\":\"专业名称1\"},{\"type\":\"major\",\"id\":\"42\",\"title\":\"专业名称2\"},{\"type\":\"major\",\"id\":\"43\",\"title\":\"专业名称3\"},{\"type\":\"major\",\"id\":\"44\",\"title\":\"专业名称4\"},{\"type\":\"major\",\"id\":\"45\",\"title\":\"专业名称5\"},{\"type\":\"news\",\"id\":\"118\",\"title\":\"坚持才会成功\"},{\"type\":\"news\",\"id\":\"117\",\"title\":\"Leave未必是一种痛苦\"},{\"type\":\"news\",\"id\":\"116\",\"title\":\"离开是一种痛苦，是一种勇气，但同样也是一个考验，是一个新的开端\"},{\"type\":\"news\",\"id\":\"115\",\"title\":\"你要去相信，没有到不了的明天\"},{\"type\":\"news\",\"id\":\"114\",\"title\":\"挫折是另一个生命的开端\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"关于我们\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"系统简介\"}]', '2026-05-03 00:36:52');
INSERT INTO `ai_chat_message` VALUES (7, 1, 'user', '你使用什么大模型？', NULL, '2026-05-03 00:37:03');
INSERT INTO `ai_chat_message` VALUES (8, 1, 'assistant', '很抱歉，我无法回答这个问题，因为数据库中没有关于我所使用的大模型的信息。我只能基于提供的上下文数据来回答相关问题。如有其他问题，请随时提问！', '[{\"type\":\"university\",\"id\":\"2049941395174621185\",\"title\":\"222\"},{\"type\":\"university\",\"id\":\"1685514620438\",\"title\":\"22225\"},{\"type\":\"university\",\"id\":\"21\",\"title\":\"学校名称1\"},{\"type\":\"university\",\"id\":\"22\",\"title\":\"学校名称2\"},{\"type\":\"university\",\"id\":\"23\",\"title\":\"学校名称3\"},{\"type\":\"major\",\"id\":\"41\",\"title\":\"专业名称1\"},{\"type\":\"major\",\"id\":\"42\",\"title\":\"专业名称2\"},{\"type\":\"major\",\"id\":\"43\",\"title\":\"专业名称3\"},{\"type\":\"major\",\"id\":\"44\",\"title\":\"专业名称4\"},{\"type\":\"major\",\"id\":\"45\",\"title\":\"专业名称5\"},{\"type\":\"news\",\"id\":\"118\",\"title\":\"坚持才会成功\"},{\"type\":\"news\",\"id\":\"117\",\"title\":\"Leave未必是一种痛苦\"},{\"type\":\"news\",\"id\":\"116\",\"title\":\"离开是一种痛苦，是一种勇气，但同样也是一个考验，是一个新的开端\"},{\"type\":\"news\",\"id\":\"115\",\"title\":\"你要去相信，没有到不了的明天\"},{\"type\":\"news\",\"id\":\"114\",\"title\":\"挫折是另一个生命的开端\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"关于我们\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"系统简介\"}]', '2026-05-03 00:37:05');
INSERT INTO `ai_chat_message` VALUES (9, 1, 'user', 'deepseek厉害吗？', NULL, '2026-05-03 00:37:31');
INSERT INTO `ai_chat_message` VALUES (10, 1, 'assistant', '对不起，我无法回答这个问题。我的知识库只包含招生相关的院校、专业、资讯和当前学生自己的信息，没有关于“deepseek”或其他人工智能模型的数据。我不能编造不存在的数据库内容。如有其他招生相关问题，欢迎提问！', '[{\"type\":\"university\",\"id\":\"2049941395174621185\",\"title\":\"222\"},{\"type\":\"university\",\"id\":\"1685514620438\",\"title\":\"22225\"},{\"type\":\"university\",\"id\":\"21\",\"title\":\"学校名称1\"},{\"type\":\"university\",\"id\":\"22\",\"title\":\"学校名称2\"},{\"type\":\"university\",\"id\":\"23\",\"title\":\"学校名称3\"},{\"type\":\"major\",\"id\":\"41\",\"title\":\"专业名称1\"},{\"type\":\"major\",\"id\":\"42\",\"title\":\"专业名称2\"},{\"type\":\"major\",\"id\":\"43\",\"title\":\"专业名称3\"},{\"type\":\"major\",\"id\":\"44\",\"title\":\"专业名称4\"},{\"type\":\"major\",\"id\":\"45\",\"title\":\"专业名称5\"},{\"type\":\"news\",\"id\":\"118\",\"title\":\"坚持才会成功\"},{\"type\":\"news\",\"id\":\"117\",\"title\":\"Leave未必是一种痛苦\"},{\"type\":\"news\",\"id\":\"116\",\"title\":\"离开是一种痛苦，是一种勇气，但同样也是一个考验，是一个新的开端\"},{\"type\":\"news\",\"id\":\"115\",\"title\":\"你要去相信，没有到不了的明天\"},{\"type\":\"news\",\"id\":\"114\",\"title\":\"挫折是另一个生命的开端\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"关于我们\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"系统简介\"}]', '2026-05-03 00:37:34');
