INSERT INTO `ai_chat_message` VALUES (12, 1, 'assistant', '好的，以下是您的个人信息：\n\n- **姓名**：学生姓名1- **学号**：学号1- **学院**：学院1- **联系电话**：13823888881如有其他需要，请随时告诉我！', '[{\"type\":\"university\",\"id\":\"2049941395174621185\",\"title\":\"222\"},{\"type\":\"university\",\"id\":\"1685514620438\",\"title\":\"22225\"},{\"type\":\"university\",\"id\":\"21\",\"title\":\"学校名称1\"},{\"type\":\"university\",\"id\":\"22\",\"title\":\"学校名称2\"},{\"type\":\"university\",\"id\":\"23\",\"title\":\"学校名称3\"},{\"type\":\"major\",\"id\":\"41\",\"title\":\"专业名称1\"},{\"type\":\"major\",\"id\":\"42\",\"title\":\"专业名称2\"},{\"type\":\"major\",\"id\":\"43\",\"title\":\"专业名称3\"},{\"type\":\"major\",\"id\":\"44\",\"title\":\"专业名称4\"},{\"type\":\"major\",\"id\":\"45\",\"title\":\"专业名称5\"},{\"type\":\"news\",\"id\":\"118\",\"title\":\"坚持才会成功\"},{\"type\":\"news\",\"id\":\"117\",\"title\":\"Leave未必是一种痛苦\"},{\"type\":\"news\",\"id\":\"116\",\"title\":\"离开是一种痛苦，是一种勇气，但同样也是一个考验，是一个新的开端\"},{\"type\":\"news\",\"id\":\"115\",\"title\":\"你要去相信，没有到不了的明天\"},{\"type\":\"news\",\"id\":\"114\",\"title\":\"挫折是另一个生命的开端\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"关于我们\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"系统简介\"}]', '2026-05-03 00:38:27');
