INSERT INTO `ai_chat_message` VALUES (80, 10, 'assistant', '好的，22222同学。以下是根据你的560分成绩，为你整理的关于“学校名称5”及其相关专业的信息。\n\n##推荐院校- **学校名称5**\n - **类型**：公办 - **层次**：985 - **联系电话**：联系方式5 - **简介**：学校简介5 - **智能推荐**：保底 - **录取分数线**：510分 - **分数优势**：高出50.0分 - **推荐理由**：你的最新成绩为560.0分，当前可覆盖该校1个专业，最高可高出分数线50.0分，属于保底院校；相似成绩学生对该校有收藏、报名或录取记录。\n\n##推荐专业- **专业名称5**\n - **所属院校**：学校名称5 - **专业代码**：专业代码5 - **录取分数线**：510分 - **分数优势**：高出50.0分 - **招生计划**：5人 - **培养方案**：培养方案5 - **推荐理由**：你的最新成绩为560.0分，已达到该专业510分的分数线，高出50.0分，属于保底选择。\n\n**填报建议**：作为985院校，“学校名称5”对你来说是稳妥的保底选择，你可以放心填报。', '[{\"type\":\"university\",\"id\":\"25\",\"title\":\"学校名称5\"},{\"type\":\"major\",\"id\":\"41\",\"title\":\"专业名称1\"},{\"type\":\"major\",\"id\":\"42\",\"title\":\"专业名称2\"},{\"type\":\"major\",\"id\":\"43\",\"title\":\"专业名称3\"},{\"type\":\"major\",\"id\":\"44\",\"title\":\"专业名称4\"},{\"type\":\"major\",\"id\":\"45\",\"title\":\"专业名称5\"},{\"type\":\"news\",\"id\":\"118\",\"title\":\"坚持才会成功\"},{\"type\":\"news\",\"id\":\"117\",\"title\":\"Leave未必是一种痛苦\"},{\"type\":\"news\",\"id\":\"116\",\"title\":\"离开是一种痛苦，是一种勇气，但同样也是一个考验，是一个新的开端\"},{\"type\":\"news\",\"id\":\"115\",\"title\":\"你要去相信，没有到不了的明天\"},{\"type\":\"news\",\"id\":\"114\",\"title\":\"挫折是另一个生命的开端\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"关于我们\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"系统简介\"},{\"type\":\"university\",\"id\":\"22\",\"title\":\"学校名称2\"},{\"type\":\"university\",\"id\":\"2049941395174621185\",\"title\":\"222\"},{\"type\":\"university\",\"id\":\"23\",\"title\":\"学校名称3\"},{\"type\":\"university\",\"id\":\"24\",\"title\":\"学校名称4\"},{\"type\":\"university\",\"id\":\"25\",\"title\":\"学校名称5\"},{\"type\":\"university\",\"id\":\"26\",\"title\":\"学校名称6\"},{\"type\":\"university\",\"id\":\"27\",\"title\":\"学校名称7\"},{\"type\":\"university\",\"id\":\"28\",\"title\":\"学校名称8\"},{\"type\":\"major\",\"id\":\"42\",\"title\":\"专业名称2\"},{\"type\":\"major\",\"id\":\"41\",\"title\":\"专业名称1\"},{\"type\":\"major\",\"id\":\"43\",\"title\":\"专业名称3\"},{\"type\":\"major\",\"id\":\"44\",\"title\":\"专业名称4\"},{\"type\":\"major\",\"id\":\"45\",\"title\":\"专业名称5\"},{\"type\":\"major\",\"id\":\"46\",\"title\":\"专业名称6\"},{\"type\":\"major\",\"id\":\"47\",\"title\":\"专业名称7\"},{\"type\":\"major\",\"id\":\"48\",\"title\":\"专业名称8\"}]', '2026-05-04 03:25:13');
INSERT INTO `ai_chat_message` VALUES (81, 10, 'user', '最新公告', NULL, '2026-05-04 03:25:59');
INSERT INTO `ai_chat_message` VALUES (82, 10, 'assistant', '好的，同学！以下是平台最近发布的资讯公告，供你参考：\n\n##最新资讯公告- **坚持才会成功**\n - **摘要**：回头看看，你会不会发现，曾经的你在这里摔倒过;回头看看，你是否发现，一次次地重复着，却从没爬起过。而如今，让我们把视线转向前方，那一道道金色的弧线，是流星飞逝的痕迹，或是成功运行的轨道。今天的你，是否要扬帆起航，让幸福来敲门?\n\n- **Leave未必是一种痛苦**\n - **摘要**：无穷无尽是离愁，天涯海角遍寻思。当离别在即之时，当面对着相濡以沫兄弟般的朋友时，当面对着经历了四年的磨合而形成的真挚友谊之时，我内心激动无语，说一声再见，道一声珍重都很难出口。\n\n- **离开是一种痛苦，是一种勇气，但同样也是一个考验，是一个新的开端**\n - **摘要**：无穷无尽是离愁，天涯海角遍寻思。当离别在即之时，当面对着相濡以沫兄弟般的朋友时，当面对着经历了四年的磨合而形成的真挚友谊之时，我内心激动无语，说一声再见，道一声珍重都很难出口。回想自己四年大学的风风雨雨，回想我们曾经共同经历的岁月流年，我感谢大家的相扶相依，感谢朋友们的莫大支持与帮助。\n\n- **你要去相信，没有到不了的明天**\n - **摘要**：有梦想就去努力，因为在这一辈子里面，现在不去勇敢的努力，也许就再也没有机会了。你要去相信，一定要相信，没有到不了的明天。不要被命运打败，让自己变得更强大。\n\n- **挫折是另一个生命的开端**\n - **摘要**：当遇到挫折或失败，你是看见失败还是看见机会?挫折是我们每个人成长的必经之路，它不是你想有就有，想没有就没有的。有句名言说的好，如果你想一生摆脱苦难，你就得是神或者是死尸。\n\n---\n以上是目前可查看的所有最新资讯，没有找到更详细的公告全文。建议你保持积极的心态，关注这些励志公告，它们或许能给你带来启发。', '[{\"type\":\"university\",\"id\":\"2049941395174621185\",\"title\":\"222\"},{\"type\":\"university\",\"id\":\"1685514620438\",\"title\":\"22225\"},{\"type\":\"university\",\"id\":\"21\",\"title\":\"学校名称1\"},{\"type\":\"university\",\"id\":\"22\",\"title\":\"学校名称2\"},{\"type\":\"university\",\"id\":\"23\",\"title\":\"学校名称3\"},{\"type\":\"major\",\"id\":\"41\",\"title\":\"专业名称1\"},{\"type\":\"major\",\"id\":\"42\",\"title\":\"专业名称2\"},{\"type\":\"major\",\"id\":\"43\",\"title\":\"专业名称3\"},{\"type\":\"major\",\"id\":\"44\",\"title\":\"专业名称4\"},{\"type\":\"major\",\"id\":\"45\",\"title\":\"专业名称5\"},{\"type\":\"news\",\"id\":\"118\",\"title\":\"坚持才会成功\"},{\"type\":\"news\",\"id\":\"117\",\"title\":\"Leave未必是一种痛苦\"},{\"type\":\"news\",\"id\":\"116\",\"title\":\"离开是一种痛苦，是一种勇气，但同样也是一个考验，是一个新的开端\"},{\"type\":\"news\",\"id\":\"115\",\"title\":\"你要去相信，没有到不了的明天\"},{\"type\":\"news\",\"id\":\"114\",\"title\":\"挫折是另一个生命的开端\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"关于我们\"},{\"type\":\"page\",\"id\":\"1\",\"title\":\"系统简介\"},{\"type\":\"university\",\"id\":\"22\",\"title\":\"学校名称2\"},{\"type\":\"university\",\"id\":\"2049941395174621185\",\"title\":\"222\"},{\"type\":\"university\",\"id\":\"23\",\"title\":\"学校名称3\"},{\"type\":\"university\",\"id\":\"24\",\"title\":\"学校名称4\"},{\"type\":\"university\",\"id\":\"25\",\"title\":\"学校名称5\"},{\"type\":\"university\",\"id\":\"26\",\"title\":\"学校名称6\"},{\"type\":\"university\",\"id\":\"27\",\"title\":\"学校名称7\"},{\"type\":\"university\",\"id\":\"28\",\"title\":\"学校名称8\"},{\"type\":\"major\",\"id\":\"42\",\"title\":\"专业名称2\"},{\"type\":\"major\",\"id\":\"41\",\"title\":\"专业名称1\"},{\"type\":\"major\",\"id\":\"43\",\"title\":\"专业名称3\"},{\"type\":\"major\",\"id\":\"44\",\"title\":\"专业名称4\"},{\"type\":\"major\",\"id\":\"45\",\"title\":\"专业名称5\"},{\"type\":\"major\",\"id\":\"46\",\"title\":\"专业名称6\"},{\"type\":\"major\",\"id\":\"47\",\"title\":\"专业名称7\"},{\"type\":\"major\",\"id\":\"48\",\"title\":\"专业名称8\"}]', '2026-05-04 03:26:10');

-- ----------------------------
-- Table structure for ai_model_config
-- ----------------------------
DROP TABLE IF EXISTS `ai_model_config`;
CREATE TABLE `ai_model_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `enabled` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否启用',
  `provider_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '服务商名称',
  `endpoint_url` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '接口地址',
  `http_method` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'POST' COMMENT '请求方法',
  `api_key` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '接口密钥',
  `headers_template` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '请求头模板JSON',
  `body_template` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '请求体模板JSON',
  `model` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '模型名称',
  `temperature` double NULL DEFAULT 0.7 COMMENT '温度参数',
  `max_tokens` int(11) NULL DEFAULT 1024 COMMENT '最大输出长度',
  `system_prompt` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '系统提示词',
  `stream_protocol` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'AUTO' COMMENT '流式协议',
  `response_text_path` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'choices.0.delta.content' COMMENT '响应文本路径',
  `done_marker` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '[DONE]' COMMENT '结束标记',
  `timeout_seconds` int(11) NULL DEFAULT 60 COMMENT '超时秒数',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'AI大模型配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_model_config
-- ----------------------------
INSERT INTO `ai_model_config` VALUES (1, 1, 'deepseek', 'https://api.deepseek.com/chat/completions', 'POST', 'sk-1fecc61421cc4e2dadbcd05a281fe257', '{\n  \"Content-Type\": \"application/json\",\n  \"Authorization\": \"Bearer {{apiKey}}\"\n}', '{\n  \"model\": \"{{model}}\",\n  \"stream\": true,\n  \"messages\": [\n    {\n      \"role\": \"system\",\n      \"content\": \"{{systemPrompt}}\\n\\n数据库上下文：\\n{{context}}\"\n    },\n    {\n      \"role\": \"user\",\n      \"content\": \"{{message}}\"\n    }\n  ],\n  \"temperature\": {{temperature}},\n  \"max_tokens\": {{maxTokens}}\n}', 'deepseek-v4-flash', 0.7, 1024, '你是大学招生平台的 AI 助手。必须基于提供的数据库上下文回答。\n可以读取公开院校、专业、资讯和当前登录学生自己的资料、报名、收藏、成绩、录取信息。\n不能编造数据库中不存在的学校、专业或学生隐私信息。没有数据时明确说明暂无数据。', 'SSE', 'choices.0.delta.content', '[DONE]', 60, '2026-05-03 00:19:46', '2026-05-03 00:19:46');

-- ----------------------------
-- Table structure for chat
-- ----------------------------
DROP TABLE IF EXISTS `chat`;
CREATE TABLE `chat`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `addtime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `userid` bigint(20) NOT NULL COMMENT '用户id',
  `adminid` bigint(20) NULL DEFAULT NULL COMMENT '管理员id',
  `ask` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '提问',
  `reply` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '回复',
  `isreply` int(11) NULL DEFAULT NULL COMMENT '是否回复',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2050893190603644931 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '在线留言' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of chat
