-- ----------------------------
-- Table structure for universityinformation
-- ----------------------------
DROP TABLE IF EXISTS `universityinformation`;
CREATE TABLE `universityinformation`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `addtime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `universityName` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '学校名称',
  `universityWebsite` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '学校网址',
  `universityImage` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '学校图片',
  `province` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '所在省份',
  `institutionType` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '院校性质',
  `keyness` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '重点程度',
  `universityIntroduction` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '学校简介',
  `majorOffered` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '开设专业',
  `phone` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '联系方式',
  `clicktime` datetime NULL DEFAULT NULL COMMENT '最近点击时间',
  `clicknum` int(11) NULL DEFAULT 0 COMMENT '点击次数',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2049941395174621186 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '院校信息' ROW_FORMAT = Dynamic;

